  final String? sourcePublishedAt;
  /// 소스가 밝힌 기준일
  final String? sourceAsOf;
  /// 월납·연납 등. 연납÷12를 월납으로 쓰지 않는다. 어휘 축 승격 대기
  final String? paymentCycle;
  /// 가격 조건(차원 -> 값). 조건 차원은 라벨 사전이 정의하는 열린 집합
