  final String? packageBinding;
  /// 원문에 없는 조건 차원
  final List<String> missingDimensions;
  final String? comparisonBasisId;
  /// 조건·구성·기준일이 모두 있고 accepted일 때만 true (K13)
  final bool comparisonEligible;
  final ValueState valueState;
  final ReviewStatus reviewStatus;
  final String? reviewDecisionId;
  /// pipeline, fixture. 어휘 축 승격 대기
  final String origin;

  const PremiumObservation({
    required this.id,
    required this.evidence,
    required this.rawAmount,
    required this.priceBasis,
    required this.observedAt,
    this.sourcePublishedAt,
    this.sourceAsOf,
    this.paymentCycle,
    this.conditions,
    this.conditionSources,
    this.packageBinding,
    required this.missingDimensions,
    this.comparisonBasisId,
    required this.comparisonEligible,
    required this.valueState,
    required this.reviewStatus,
    this.reviewDecisionId,
    required this.origin,
  });

  factory PremiumObservation.fromJson(Map<String, dynamic> json) => PremiumObservation(
        id: json['id'] as String,
        evidence: (json['evidence'] as List<dynamic>).map((e) => EvidenceLink.fromJson(e as Map<String, dynamic>)).toList(),
        rawAmount: json['raw_amount'] as int,
        priceBasis: PriceBasis.fromJson(json['price_basis'] as String),
        observedAt: json['observed_at'] as String,
        sourcePublishedAt: json['source_published_at'] == null ? null : json['source_published_at'] as String,
        sourceAsOf: json['source_as_of'] == null ? null : json['source_as_of'] as String,
        paymentCycle: json['payment_cycle'] == null ? null : json['payment_cycle'] as String,
        conditions: json['conditions'] == null ? null : (json['conditions'] as Map<String, dynamic>).map((k, v) => MapEntry(k, v as String)),
        conditionSources: json['condition_sources'] == null ? null : (json['condition_sources'] as Map<String, dynamic>).map((k, v) => MapEntry(k, v as String)),
        packageBinding: json['package_binding'] == null ? null : json['package_binding'] as String,
        missingDimensions: (json['missing_dimensions'] as List<dynamic>).map((e) => e as String).toList(),
        comparisonBasisId: json['comparison_basis_id'] == null ? null : json['comparison_basis_id'] as String,
        comparisonEligible: json['comparison_eligible'] as bool,
        valueState: ValueState.fromJson(json['value_state'] as String),
        reviewStatus: ReviewStatus.fromJson(json['review_status'] as String),
        reviewDecisionId: json['review_decision_id'] == null ? null : json['review_decision_id'] as String,
        origin: json['origin'] as String,
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'evidence': evidence.map((e) => e.toJson()).toList(),
        'raw_amount': rawAmount,
        'price_basis': priceBasis.toJson(),
        'observed_at': observedAt,
        if (sourcePublishedAt != null) 'source_published_at': sourcePublishedAt!,
        if (sourceAsOf != null) 'source_as_of': sourceAsOf!,
        if (paymentCycle != null) 'payment_cycle': paymentCycle!,
        if (conditions != null) 'conditions': conditions!.map((k, v) => MapEntry(k, v)),
        if (conditionSources != null) 'condition_sources': conditionSources!.map((k, v) => MapEntry(k, v)),
        if (packageBinding != null) 'package_binding': packageBinding!,
        'missing_dimensions': missingDimensions.map((e) => e).toList(),
        if (comparisonBasisId != null) 'comparison_basis_id': comparisonBasisId!,
        'comparison_eligible': comparisonEligible,
        'value_state': valueState.toJson(),
        'review_status': reviewStatus.toJson(),
        if (reviewDecisionId != null) 'review_decision_id': reviewDecisionId!,
        'origin': origin,
      };
}

/// 릴리스가 읽는 구성원 ID 목록(정렬). 이 목록뿐이다 (02 §1.3)
class ReleaseMembers {
  final List<String> rawAssets;
  final List<String> segments;
  final List<String> termsEditions;
  final List<String> termsLineages;
  final List<String> clauses;
  final List<String> nodes;
  final List<String> assertions;
  final List<String> conflicts;
  final List<String> gaps;
  final List<String> premiumObservations;
  /// 판단 기준 릴리스는 별도 ID로 고정하고 참조만 한다
  final String? criteriaReleaseRef;

  const ReleaseMembers({
    required this.rawAssets,
    required this.segments,
    required this.termsEditions,
    required this.termsLineages,
    required this.clauses,
    required this.nodes,
    required this.assertions,
    required this.conflicts,
    required this.gaps,
    required this.premiumObservations,
    this.criteriaReleaseRef,
  });

  factory ReleaseMembers.fromJson(Map<String, dynamic> json) => ReleaseMembers(
        rawAssets: (json['raw_assets'] as List<dynamic>).map((e) => e as String).toList(),
        segments: (json['segments'] as List<dynamic>).map((e) => e as String).toList(),
        termsEditions: (json['terms_editions'] as List<dynamic>).map((e) => e as String).toList(),
        termsLineages: (json['terms_lineages'] as List<dynamic>).map((e) => e as String).toList(),
        clauses: (json['clauses'] as List<dynamic>).map((e) => e as String).toList(),
        nodes: (json['nodes'] as List<dynamic>).map((e) => e as String).toList(),
        assertions: (json['assertions'] as List<dynamic>).map((e) => e as String).toList(),
        conflicts: (json['conflicts'] as List<dynamic>).map((e) => e as String).toList(),
        gaps: (json['gaps'] as List<dynamic>).map((e) => e as String).toList(),
        premiumObservations: (json['premium_observations'] as List<dynamic>).map((e) => e as String).toList(),
        criteriaReleaseRef: json['criteria_release_ref'] == null ? null : json['criteria_release_ref'] as String,
      );

  Map<String, dynamic> toJson() => {
        'raw_assets': rawAssets.map((e) => e).toList(),
        'segments': segments.map((e) => e).toList(),
        'terms_editions': termsEditions.map((e) => e).toList(),
        'terms_lineages': termsLineages.map((e) => e).toList(),
        'clauses': clauses.map((e) => e).toList(),
        'nodes': nodes.map((e) => e).toList(),
        'assertions': assertions.map((e) => e).toList(),
        'conflicts': conflicts.map((e) => e).toList(),
        'gaps': gaps.map((e) => e).toList(),
        'premium_observations': premiumObservations.map((e) => e).toList(),
        if (criteriaReleaseRef != null) 'criteria_release_ref': criteriaReleaseRef!,
      };
}

/// 사용한 모델. 식별자 원문은 싣지 않고 해시만 싣는다
class ModelVersion {
  /// 제공자 계열 라벨
  final String providerFamilyLabel;
  final String modelRefHash;
  final String promptVersion;

  const ModelVersion({
    required this.providerFamilyLabel,
    required this.modelRefHash,
    required this.promptVersion,
  });

  factory ModelVersion.fromJson(Map<String, dynamic> json) => ModelVersion(
        providerFamilyLabel: json['provider_family_label'] as String,
        modelRefHash: json['model_ref_hash'] as String,
        promptVersion: json['prompt_version'] as String,
      );

  Map<String, dynamic> toJson() => {
        'provider_family_label': providerFamilyLabel,
        'model_ref_hash': modelRefHash,
        'prompt_version': promptVersion,
      };
}

/// 릴리스 manifest. 불변이며 롤백은 manifest 교체다 (02_구현계약 §1.3)
class ReleaseManifest {
  final String releaseId;
  final String createdAt;
  final String frozenAt;
  final ReleaseMembers members;
  /// 규칙 파일 경로 -> 바이트 해시
  final Map<String, String> ruleFiles;
  /// 입력 단계 판정 규칙의 판 (소속·시간·연결 검증)
  final String inputStageEdition;
  /// members가 가리키는 행 내용 + rule_files를 정규화(JSON, 키 정렬)한 SHA-256
  final String contentSha256;
  final String ontoVersion;
  final String vocabularyVersion;
  final String labelDictionaryVersion;
  /// contracts 패키지 semver
  final String schemaVersion;
  final List<String> extractorVersions;
  final List<ModelVersion> modelVersions;
  final String engineVersion;
  final List<String> ruleSchemaVersions;
  final String capabilityTableHash;
  final String explainTemplateHash;
  /// 이전 릴리스와 같은 입력 비교 결과. 첫 릴리스는 비교 대상이 없어 생략
  final String? shadowCompareReportId;
  /// K1~K16 위반 0건 보고
  final String constraintReportId;
  final String? supersededBy;
  final String? withdrawnAt;
  final String? withdrawalReason;

  const ReleaseManifest({
    required this.releaseId,
    required this.createdAt,
    required this.frozenAt,
    required this.members,
    required this.ruleFiles,
    required this.inputStageEdition,
    required this.contentSha256,
    required this.ontoVersion,
    required this.vocabularyVersion,
    required this.labelDictionaryVersion,
    required this.schemaVersion,
    required this.extractorVersions,
    required this.modelVersions,
    required this.engineVersion,
    required this.ruleSchemaVersions,
    required this.capabilityTableHash,
    required this.explainTemplateHash,
    this.shadowCompareReportId,
    required this.constraintReportId,
    this.supersededBy,
    this.withdrawnAt,
    this.withdrawalReason,
  });

  factory ReleaseManifest.fromJson(Map<String, dynamic> json) => ReleaseManifest(
        releaseId: json['release_id'] as String,
        createdAt: json['created_at'] as String,
        frozenAt: json['frozen_at'] as String,
        members: ReleaseMembers.fromJson(json['members'] as Map<String, dynamic>),
        ruleFiles: (json['rule_files'] as Map<String, dynamic>).map((k, v) => MapEntry(k, v as String)),
        inputStageEdition: json['input_stage_edition'] as String,
        contentSha256: json['content_sha256'] as String,
        ontoVersion: json['onto_version'] as String,
        vocabularyVersion: json['vocabulary_version'] as String,
        labelDictionaryVersion: json['label_dictionary_version'] as String,
        schemaVersion: json['schema_version'] as String,
        extractorVersions: (json['extractor_versions'] as List<dynamic>).map((e) => e as String).toList(),
        modelVersions: (json['model_versions'] as List<dynamic>).map((e) => ModelVersion.fromJson(e as Map<String, dynamic>)).toList(),
        engineVersion: json['engine_version'] as String,
        ruleSchemaVersions: (json['rule_schema_versions'] as List<dynamic>).map((e) => e as String).toList(),
        capabilityTableHash: json['capability_table_hash'] as String,
        explainTemplateHash: json['explain_template_hash'] as String,
        shadowCompareReportId: json['shadow_compare_report_id'] == null ? null : json['shadow_compare_report_id'] as String,
        constraintReportId: json['constraint_report_id'] as String,
        supersededBy: json['superseded_by'] == null ? null : json['superseded_by'] as String,
        withdrawnAt: json['withdrawn_at'] == null ? null : json['withdrawn_at'] as String,
        withdrawalReason: json['withdrawal_reason'] == null ? null : json['withdrawal_reason'] as String,
      );

  Map<String, dynamic> toJson() => {
        'release_id': releaseId,
        'created_at': createdAt,
        'frozen_at': frozenAt,
        'members': members.toJson(),
        'rule_files': ruleFiles.map((k, v) => MapEntry(k, v)),
        'input_stage_edition': inputStageEdition,
        'content_sha256': contentSha256,
        'onto_version': ontoVersion,
        'vocabulary_version': vocabularyVersion,
        'label_dictionary_version': labelDictionaryVersion,
        'schema_version': schemaVersion,
        'extractor_versions': extractorVersions.map((e) => e).toList(),
        'model_versions': modelVersions.map((e) => e.toJson()).toList(),
        'engine_version': engineVersion,
        'rule_schema_versions': ruleSchemaVersions.map((e) => e).toList(),
        'capability_table_hash': capabilityTableHash,
        'explain_template_hash': explainTemplateHash,
        if (shadowCompareReportId != null) 'shadow_compare_report_id': shadowCompareReportId!,
        'constraint_report_id': constraintReportId,
        if (supersededBy != null) 'superseded_by': supersededBy!,
        if (withdrawnAt != null) 'withdrawn_at': withdrawnAt!,
        if (withdrawalReason != null) 'withdrawal_reason': withdrawalReason!,
      };
}

/// 입력 단계 판정. 규칙 근거와 분리한다 (02 §2.4)
class InputJudgement {
  final String inputName;
  final Tri value;
  /// 판정 주체. 02 §2.4에 값 집합이 없다. 어휘 축 승격 대기
  final String judgedBy;
  final List<String> evidenceAssertionIds;

  const InputJudgement({
    required this.inputName,
    required this.value,
    required this.judgedBy,
    required this.evidenceAssertionIds,
  });

  factory InputJudgement.fromJson(Map<String, dynamic> json) => InputJudgement(
        inputName: json['input_name'] as String,
        value: Tri.fromJson(json['value'] as String),
        judgedBy: json['judged_by'] as String,
        evidenceAssertionIds: (json['evidence_assertion_ids'] as List<dynamic>).map((e) => e as String).toList(),
      );

  Map<String, dynamic> toJson() => {
        'input_name': inputName,
        'value': value.toJson(),
        'judged_by': judgedBy,
        'evidence_assertion_ids': evidenceAssertionIds.map((e) => e).toList(),
      };
}

/// 입력 단계가 계산을 막은 이유 (02 §1.7 resolve_chain Blocked)
class BlockedBy {
  /// no_uses_edition, multiple_candidates, scope_unknown, application_scope_unverified, applies_from_other_edition_unmodeled, competing_editions, link_unapproved, edition_identity_unconfirmed, cov_not_in_edition, no_rule. 어휘 축 승격 대기
  final String reason;
  final List<String> heldConclusions;

  const BlockedBy({
    required this.reason,
    required this.heldConclusions,
  });

  factory BlockedBy.fromJson(Map<String, dynamic> json) => BlockedBy(
        reason: json['reason'] as String,
        heldConclusions: (json['held_conclusions'] as List<dynamic>).map((e) => e as String).toList(),
      );

  Map<String, dynamic> toJson() => {
        'reason': reason,
        'held_conclusions': heldConclusions.map((e) => e).toList(),
      };
}

/// 설명 문장. 금액은 금액마다 출처를 선언한다
class Explain {
  final String templateId;
  final String text;
  final List<Amount> amounts;

  const Explain({
    required this.templateId,
    required this.text,
    required this.amounts,
  });

  factory Explain.fromJson(Map<String, dynamic> json) => Explain(
        templateId: json['template_id'] as String,
        text: json['text'] as String,
        amounts: (json['amounts'] as List<dynamic>).map((e) => Amount.fromJson(e as Map<String, dynamic>)).toList(),
      );

  Map<String, dynamic> toJson() => {
        'template_id': templateId,
        'text': text,
        'amounts': amounts.map((e) => e.toJson()).toList(),
      };
}

/// 시나리오 결과: EvaluationResult + 입력 단계 판정 + 설명 + 막힘 (02_구현계약 §2.1·§2.4)
class ScenarioResult {
  /// 모든 응답은 release_id를 echo한다
  final String releaseId;
  final String covId;
  /// 엔진 결과. 막혔으면(blocked_by) 엔진 호출 0건이라 없다
  final EvaluationResult? evaluation;
  final List<InputJudgement> judgements;
  final List<BlockedBy> blockedBy;
  final List<String> remainingGaps;
  final Explain? explain;
  final DisplayStatus displayStatus;
  final ResultState resultState;
  final DependencyInfo? dependency;

  const ScenarioResult({
    required this.releaseId,
    required this.covId,
    this.evaluation,
    required this.judgements,
    required this.blockedBy,
    required this.remainingGaps,
    this.explain,
    required this.displayStatus,
    required this.resultState,
    this.dependency,
  });

  factory ScenarioResult.fromJson(Map<String, dynamic> json) => ScenarioResult(
        releaseId: json['release_id'] as String,
        covId: json['cov_id'] as String,
        evaluation: json['evaluation'] == null ? null : EvaluationResult.fromJson(json['evaluation'] as Map<String, dynamic>),
        judgements: (json['judgements'] as List<dynamic>).map((e) => InputJudgement.fromJson(e as Map<String, dynamic>)).toList(),
        blockedBy: (json['blocked_by'] as List<dynamic>).map((e) => BlockedBy.fromJson(e as Map<String, dynamic>)).toList(),
        remainingGaps: (json['remaining_gaps'] as List<dynamic>).map((e) => e as String).toList(),
        explain: json['explain'] == null ? null : Explain.fromJson(json['explain'] as Map<String, dynamic>),
        displayStatus: DisplayStatus.fromJson(json['display_status'] as String),
        resultState: ResultState.fromJson(json['result_state'] as Map<String, dynamic>),
        dependency: json['dependency'] == null ? null : DependencyInfo.fromJson(json['dependency'] as Map<String, dynamic>),
      );

  Map<String, dynamic> toJson() => {
        'release_id': releaseId,
        'cov_id': covId,
        if (evaluation != null) 'evaluation': evaluation!.toJson(),
        'judgements': judgements.map((e) => e.toJson()).toList(),
        'blocked_by': blockedBy.map((e) => e.toJson()).toList(),
        'remaining_gaps': remainingGaps.map((e) => e).toList(),
        if (explain != null) 'explain': explain!.toJson(),
        'display_status': displayStatus.toJson(),
        'result_state': resultState.toJson(),
        if (dependency != null) 'dependency': dependency!.toJson(),
      };
}
